using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Security.Cryptography;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.EventSystems;using UnityEngine.Rendering.Universal;using Object=UnityEngine.Object;
namespace Maze.EditorTools {
[InitializeOnLoad]public static class GearTidyProof {
const string Key="Maze.GearTidyProof.Active";const BindingFlags Flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
static string Out=>Environment.GetEnvironmentVariable("GEAR_TIDY_OUT")??"Logs/GearTidyProof";static Game G=>Object.FindAnyObjectByType<Game>();static MenuPresentation P=>G.menu.Presentation;static TitleScreenView Title=>G.menu.GetComponent<TitleScreenView>();
[Serializable]class Report{public string utc,savedBefore,savedAfter;public List<string>tests=new(),errors=new(),warnings=new(),captures=new();}static Report report;static List<Action>steps;static int step,frame,width,height;static double start=-1,next;static bool prepared,done,oldSim;static string originalProgress,oldHeroOverride;static Camera ui;static RenderTexture target;static Rect safePixels;static Dictionary<string,(bool had,int integer)> ints=new();static Dictionary<string,(bool had,string value)>strings=new();
static GearTidyProof(){if(SessionState.GetBool(Key,false))Hook();}public static void Run(){MenuFidelityImporter.Import();TitleScreenImporter.Import();SessionState.SetBool(Key,true);Hook();EditorSceneManager.OpenScene("Assets/Maze/Scenes/Main.unity");EditorApplication.EnterPlaymode();}
static void Hook(){EditorApplication.update-=Tick;EditorApplication.update+=Tick;Application.logMessageReceived-=Logged;Application.logMessageReceived+=Logged;}static void Logged(string msg,string stack,LogType t){if(done||!SessionState.GetBool(Key,false))return;report??=new Report();if(t==LogType.Exception||t==LogType.Error||t==LogType.Assert)report.errors.Add(msg+"\n"+stack);else if(t==LogType.Warning)report.warnings.Add(msg);}
static void Check(bool ok,string msg){report.tests.Add((ok?"PASS ":"FAIL ")+msg);if(!ok)report.errors.Add(msg);}static void Wait(double seconds=.6){next=EditorApplication.timeSinceStartup+seconds;frame=Time.frameCount+8;}static T Field<T>(object o,string n)=>(T)o.GetType().GetField(n,Flags).GetValue(o);
static string Hash(byte[] b){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}static string Saved()=>Hash(System.Text.Encoding.UTF8.GetBytes(PlayerPrefs.GetString("ms.progress","")));
static void Tick(){if(done)return;if(start<0)start=EditorApplication.timeSinceStartup;if(EditorApplication.timeSinceStartup-start>320){Finish("Timed out");return;}if(!EditorApplication.isPlaying||G==null||G.menu==null||P==null||Camera.main==null)return;try{if(!prepared){Prepare();return;}if(EditorApplication.timeSinceStartup<next||Time.frameCount<frame)return;if(step>=steps.Count){Finish();return;}steps[step++]();}catch(Exception e){Finish(e.ToString());}}
static void Prepare(){report??=new Report();report.utc=DateTime.UtcNow.ToString("O");report.savedBefore=Saved();oldSim=Progress.Sim;originalProgress=JsonUtility.ToJson(Progress.D);oldHeroOverride=Prefs.HeroOverride;
foreach(var key in new[]{"ms.sector","ms.difficulty","ms.tut.armory","ms.best","ms.test.floor","ms.test.mode"}.Concat(SectorDefs.All.Select(d=>"ms.seen."+d.id)))ints[key]=(PlayerPrefs.HasKey(key),PlayerPrefs.GetInt(key));foreach(var key in new[]{"ms.hero","ms.weapon"})strings[key]=(PlayerPrefs.HasKey(key),PlayerPrefs.GetString(key));
Progress.Sim=true;var temp=JsonUtility.FromJson<SaveData>(File.ReadAllText(Environment.GetEnvironmentVariable("GEAR_TIDY_SAVE")));temp.runs=Mathf.Max(5,temp.runs);Progress.UseTemp(temp);Prefs.HeroOverride="vanguard";G.player.RebuildHero(G.cfg);AudioListener.pause=true;AudioListener.volume=0;Directory.CreateDirectory(Out);prepared=true;
steps=new List<Action>{()=>{Resize(1672,941);G.menu.Show();Wait();},()=>{Title.PlayButton.onClick.Invoke();Wait(1);},()=>{P.OpenWeapons();Wait();}};
foreach(var size in new[]{new Vector2Int(1672,941),new Vector2Int(2868,1320)}){var q=size;
steps.Add(()=>{Resize(q.x,q.y);P.OpenWeapons();Wait();});
steps.Add(()=>{Inspect("gear_"+q.x);Shot("gear_"+q.x);var b=P.GetComponentsInChildren<UnityEngine.UI.Button>(false).First(x=>x.name=="WeaponCard1");b.onClick.Invoke();Wait();});
steps.Add(()=>{Check(Field<int>(P,"previewWeapon")>=0,"Thermal card binds actual weapon");Shot("thermal_"+q.x);P.GetComponentsInChildren<UnityEngine.UI.Button>(false).First(x=>x.name=="WeaponCard2").onClick.Invoke();Wait();});
steps.Add(()=>{Shot("rail_"+q.x);P.Back();G.menu.OpenSheet("gear");Wait();});
steps.Add(()=>{G.menu.Gear.ChooseFilter(-1);Wait();});
steps.Add(()=>{Check(G.menu.Gear.Visible,"actual equipment inventory opened");Check(G.menu.Gear.VisibleCount==Progress.D.gear.Count,"all saved items represented");Inspect("inventory_"+q.x);InventoryLayoutChecks();Shot("inventory_"+q.x);G.menu.Gear.ChooseFilter(1);Wait();});
steps.Add(()=>{Check(G.menu.Gear.VisibleUids.All(id=>Progress.Item(id).slot==1),"Vest filter retains real item identity");Shot("inventory_vest_"+q.x);G.menu.Gear.ChooseFilter(3);Wait();});
steps.Add(()=>{Check(G.menu.Gear.VisibleCount==0,"empty Boots filter reflects real saved inventory");Shot("inventory_empty_"+q.x);G.menu.Gear.Back();Wait();});
}

}
static void InventoryLayoutChecks(){var v=G.menu.Gear;var panel=v.GetComponentsInChildren<RectTransform>(true).First(x=>x.name=="DetailsPanel");var p=Bounds(panel);var bs=new[]{v.EquipButton,v.UpgradeButton,v.MergeButton,v.LockButton,v.SalvageButton};foreach(var b in bs){var surface=(RectTransform)b.transform.Find("Surface");var r=Bounds(surface);Check(r.xMin>=p.xMin&&r.xMax<=p.xMax&&r.yMin>=p.yMin&&r.yMax<=p.yMax,b.name+" visible face inside detail panel");}for(int i=0;i<bs.Length;i++)for(int j=i+1;j<bs.Length;j++)Check(!Bounds((RectTransform)bs[i].transform).Overlaps(Bounds((RectTransform)bs[j].transform)),bs[i].name+" / "+bs[j].name+" touch areas do not overlap");}
static void MigrationChecks(){foreach(var hero in new[]{"sentinel","scout","vanguard"}){var d=new SaveData{credits=724,parts=41,alloy=26,runs=11};d.heroLv.Add("sentinel:12");d.heroLv.Add("vanguard:4");d.heroStars.Add("scout:3");d.shards.Add("sentinel:7");d.shards.Add("scout:9");d.shards.Add("vanguard:3");d.cleared.Add("cryo-station");d.gear.Add(new GearItem{uid=7,slot=1,rarity=2,level=4});d.equipped[1]=7;string inv=JsonUtility.ToJson(d.gear[0]);HeavyRoster.Migrate(d,hero);Check(d.credits==724&&d.parts==41&&d.alloy==26&&d.runs==11&&d.equipped[1]==7&&JsonUtility.ToJson(d.gear[0])==inv&&d.cleared.Contains("cryo-station"),hero+" migration preserves currency, inventory and unlocks");Check(d.heroLv.Contains("vanguard:12")&&d.heroStars.Contains("vanguard:3")&&d.shards.Contains("vanguard:19"),hero+" migration retains hero progression");string once=JsonUtility.ToJson(d);HeavyRoster.Migrate(d,"vanguard");Check(once==JsonUtility.ToJson(d),hero+" migration is idempotent");}Check(Resources.Load<GameObject>("Models/hero")==null&&Resources.Load<GameObject>("Models/hero_scout")==null,"removed hero models are absent from Resources");Check(Resources.Load<GameObject>("Models/hero_vanguard_meshy")!=null,"approved Heavy model remains available");}
static void Inspect(string label){Canvas.ForceUpdateCanvases();var canvases=Object.FindObjectsByType<Canvas>();Check(Object.FindObjectsByType<EventSystem>().Length==1,label+" one EventSystem");var b=canvases.Where(c=>c.enabled).SelectMany(c=>c.GetComponentsInChildren<UnityEngine.UI.Button>(false));foreach(var button in b){if(!button.IsActive())continue;var r=Bounds((RectTransform)button.transform);Check(r.xMin>=safePixels.xMin-2&&r.xMax<=safePixels.xMax+2&&r.yMin>=safePixels.yMin-2&&r.yMax<=safePixels.yMax+2,label+" "+button.name+" within safe area");Check(r.width/height*375>=44&&r.height/height*375>=44,label+" "+button.name+" target at least44pt");}}
        static void Resize(int w,int h,bool asymmetric=false)
        {
            width=w;height=h;if(target!=null){Camera.main.targetTexture=null;if(ui!=null)ui.targetTexture=null;target.Release();Object.DestroyImmediate(target);}
            target=new RenderTexture(w,h,24,RenderTextureFormat.ARGB32){antiAliasing=1,name="GearTidyProof"};target.Create();Camera.main.targetTexture=target;
            if(ui==null){ui=new GameObject("GearTidyProofUiCamera").AddComponent<Camera>();ui.cullingMask=1<<5;ui.orthographic=true;ui.nearClipPlane=.1f;ui.farClipPlane=200;ui.transform.position=new Vector3(0,-2000,0);ui.GetUniversalAdditionalCameraData().renderType=CameraRenderType.Overlay;Camera.main.GetUniversalAdditionalCameraData().cameraStack.Add(ui);}
            ui.targetTexture=target;float l=w/(float)h>2?Mathf.Round(177*w/2556f):0,r=w/(float)h>2?Mathf.Round((asymmetric?132:177)*w/2556f):0,b=w/(float)h>2?Mathf.Round(63*h/1179f):0;safePixels=new Rect(l,b,w-l-r,h-b);SafeArea.Override=new Rect(l/w,b/h,1-(l+r)/w,1-b/h);
            foreach(var c in Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include))
            {
                if(!c.isRootCanvas)continue;int order=c.sortingOrder;c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=ui;c.planeDistance=50;c.sortingOrder=order;
                var sc=c.GetComponent<UnityEngine.UI.CanvasScaler>();if(sc!=null&&c.name!="TitleScreenCanvas"){sc.uiScaleMode=UnityEngine.UI.CanvasScaler.ScaleMode.ConstantPixelSize;sc.scaleFactor=h/1080f;}
            }
        }
        static Rect Bounds(RectTransform rt){var cs=new Vector3[4];rt.GetWorldCorners(cs);var a=RectTransformUtility.WorldToScreenPoint(ui,cs[0]);var b=RectTransformUtility.WorldToScreenPoint(ui,cs[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
        static string Shot(string name)
        {
            var old=RenderTexture.active;RenderTexture.active=target;var tex=new Texture2D(width,height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();RenderTexture.active=old;var png=tex.EncodeToPNG();string file=Path.Combine(Out,name+".png");File.WriteAllBytes(file,png);Object.DestroyImmediate(tex);report.captures.Add(file);Debug.Log("GearTidyProof capture "+name);return Hash(png);
        }
static void Finish(string error=null){if(done)return;done=true;report??=new Report();if(error!=null)report.errors.Add(error);try{if(prepared){report.savedAfter=Saved();Check(report.savedBefore==report.savedAfter,"saved progress unchanged");Progress.UseTemp(JsonUtility.FromJson<SaveData>(originalProgress));Progress.Sim=oldSim;Prefs.HeroOverride=oldHeroOverride;foreach(var kv in ints){if(kv.Value.had)PlayerPrefs.SetInt(kv.Key,kv.Value.integer);else PlayerPrefs.DeleteKey(kv.Key);}foreach(var kv in strings){if(kv.Value.had)PlayerPrefs.SetString(kv.Key,kv.Value.value);else PlayerPrefs.DeleteKey(kv.Key);}PlayerPrefs.Save();SafeArea.Override=null;}Directory.CreateDirectory(Out);File.WriteAllText(Path.Combine(Out,"report.json"),JsonUtility.ToJson(report,true));}catch(Exception e){Debug.LogError(e);}SessionState.SetBool(Key,false);EditorApplication.update-=Tick;Application.logMessageReceived-=Logged;Debug.Log("GearTidyProof complete:"+report.tests.Count+"checks,"+report.errors.Count+"errors");EditorApplication.Exit(report.errors.Count==0?0:1);}
}}
